/* Accessible Finance row/card triggers: touch, mouse, keyboard, focus return and axe. */
const {chromium}=require('playwright');const {expect}=require('playwright/test');const assert=require('node:assert/strict');const fs=require('node:fs');const path=require('node:path');
const sizes=process.env.DEEP_AUDIT_SMOKE?[[390,844]]:[[320,700],[360,800],[390,844],[430,932],[768,1024],[1024,768],[1280,800],[1440,900]],languages=process.env.DEEP_AUDIT_SMOKE?['English + Bangla']:['English','English + Bangla','Bangla'];const port=Number(process.env.DEEP_AUDIT_PORT||4498),output=process.env.DEEP_AUDIT_OUTPUT||'.superpowers/deep-audit/finance-actions',results=[];
async function main(){const {createServer}=await import('vite');const server=await createServer({cacheDir:'.superpowers/finance-actions-cache-'+port,server:{host:'127.0.0.1',port,strictPort:true}});await server.listen();const browser=await chromium.launch({executablePath:process.env.PLAYWRIGHT_EXECUTABLE_PATH||undefined,args:['--no-sandbox']});fs.mkdirSync(output,{recursive:true});try{for(const [width,height]of sizes.filter(size=>!process.env.DEEP_AUDIT_WIDTH||size[0]===Number(process.env.DEEP_AUDIT_WIDTH)))for(const theme of ['light','dark'])for(const language of languages){const bn=language==='Bangla',id=width+'-'+theme+'-'+language.replaceAll(' ','');const context=await browser.newContext({viewport:{width,height},hasTouch:width<=1024,colorScheme:theme,reducedMotion:'reduce'});await context.addInitScript(({theme,language})=>{localStorage.setItem('hisabiq-theme',theme);localStorage.setItem('hisabiq-erp-personal-v1',JSON.stringify({mode:'Simple',language,density:'Compact',terminology:'simple',dateView:'transaction'}));},{theme,language});await context.tracing.start({screenshots:true,snapshots:true,sources:true});const page=await context.newPage();page.setDefaultNavigationTimeout(60000);await page.route('https://fonts.googleapis.com/**',r=>r.abort());const errors=[];page.on('pageerror',e=>errors.push(e.message));await page.goto(`http://127.0.0.1:${port}/#/app/finance`,{waitUntil:'domcontentloaded'});const word=(en,bangla)=>bn?bangla:en,prefix=word('Actions for ','কাজ ');const act=e=>width<=1024?e.tap():e.click();
const axe=async()=>{await page.addScriptTag({path:require.resolve('axe-core/axe.min.js')});const violations=await page.evaluate(async()=>{const r=await window.axe.run(document.querySelector('main'),{runOnly:{type:'tag',values:['wcag2a','wcag2aa','wcag21a','wcag21aa','wcag22aa']}});return r.violations.map(v=>({id:v.id,impact:v.impact,targets:v.nodes.map(n=>n.target)}));});assert.deepEqual(violations,[],'targeted Finance tab axe findings');};
for(const [name,tab,record,count]of [['transaction',word('Loans & Owners','ঋণ ও মালিক'),'FIN-000188',5],['account',word('Money Accounts','টাকার হিসাব'),'Main Cash Counter',5],['transfer',word('Money Accounts','টাকার হিসাব'),'TRF-000041',3]]){try{await act(page.getByRole('tab',{name:tab,exact:true}));if(name==='transaction')await expect(page.getByRole('button',{name:new RegExp('^'+prefix+'FIN-')})).toHaveCount(count);if(name==='transfer')await expect(page.getByRole('button',{name:new RegExp('^'+prefix+'TRF-')})).toHaveCount(count);if(name==='account')for(const account of ['Main Cash Counter','Dutch-Bangla Bank · 4582','BRAC Bank · 7714','bKash Business · 412','Nagad Merchant · 771'])await expect(page.getByRole('button',{name:prefix+account,exact:true})).toHaveCount(1);
const trigger=page.getByRole('button',{name:prefix+record,exact:true});await act(trigger);const dialog=page.getByRole('dialog');await expect(dialog).toBeVisible();await expect(dialog).toContainText(record);await expect(page.locator('body')).toHaveCSS('overflow','hidden');const box=await dialog.boundingBox();assert.ok(box.x>=-1&&box.x+box.width<=width+1&&box.y>=-1&&box.y+box.height<=height+1,'dialog fits viewport');await page.keyboard.press('Escape');await expect(dialog).toBeHidden();await expect(trigger).toBeFocused();await trigger.press('Enter');await expect(dialog).toBeVisible();await page.keyboard.press('Escape');await expect(dialog).toBeHidden();await expect(trigger).toBeFocused();if([390,1440].includes(width)&&name!=='transfer')await axe();assert.deepEqual(errors,[]);results.push({id,name,status:'passed',axe:[390,1440].includes(width)&&name!=='transfer'});}catch(e){results.push({id,name,status:'failed',error:e.message});console.error(id,name,e.message);await page.screenshot({path:path.join(output,id+'-'+name+'.png'),fullPage:true});}}
await context.tracing.stop(results.some(r=>r.id===id&&r.status==='failed')?{path:path.join(output,id+'-trace.zip')}:{});await context.close();console.log(id,results.filter(r=>r.id===id).map(r=>r.name+':'+r.status).join(','));}}finally{fs.writeFileSync(path.join(output,'results.json'),JSON.stringify(results,null,2));await browser.close();await server.close();}console.log(results.length+' journeys; '+results.filter(r=>r.status==='failed').length+' failed');assert.equal(results.filter(r=>r.status==='failed').length,0);}
main().catch(e=>{console.error(e);process.exitCode=1;});
